const chronologySubmit=extraSubmit;
extraSubmit=function(form,data,m){const v=k=>String(data.get(k)||'').trim();if(form.dataset.form==='earlier-self'){if(mutate('Added an earlier self',pr=>{W.addEarlierSelf(pr,m.id,{earlierLabel:v('earlierLabel'),preservedLabel:v('preservedLabel'),storyDate:v('storyDate'),seed:v('seed'),lifeStatus:v('lifeStatus')});ui.at='';}))closeDialog();return true;}if(form.dataset.form==='faction-transition'){if(mutate('Kept faction transition',pr=>W.transitionFaction(pr,{sourceId:m.id,partnerId:v('partnerId'),mode:v('mode'),names:v('names').split('\n'),moment:v('moment'),memberIds:data.getAll('members')})))closeDialog();return true;}return chronologySubmit(form,data,m);};
function evidenceEditor(id,evidenceId=''){const n=node(id);if(!n||n.type!=='I'){toast('Choose an Inquiry thread.');return;}const link=(n.evidenceLinks||[]).find(x=>x.id===evidenceId)||{sourceType:'fact',sourceId:'',bearing:'supports',note:''};modalData={kind:'evidence',id,evidenceId};dialog('INQUIRY EVIDENCE','What bears on this question?',select('Existing fact or scene','source',[['','Choose evidence'],...p().world.filter(w=>w.type==='fact').map(w=>['fact:'+w.id,w.name]),...W.reading(p()).map(s=>['scene:'+(s.sceneId||s.writingId),name(s)])],link.sourceId?link.sourceType+':'+link.sourceId:'')+select('How it bears on the answer','bearing',[['supports','Supports'],['challenges','Challenges'],['complicates','Complicates']],link.bearing)+field('Why?','note',link.note,'','textarea'),submit('Keep evidence link'),'evidence');}
const detailWithEvidence=sceneDetails;
sceneDetails=function(id){detailWithEvidence(id);const n=node(id);if(n?.type==='I')$('#dialog .dialog-body').insertAdjacentHTML('beforeend',disclosure('Evidence and interpretation',(n.evidenceLinks||[]).map(x=>`<article class="history-row"><strong>${esc(x.bearing)} · ${esc(p().world.find(w=>w.id===x.sourceId)?.name||W.allNodes(p()).find(s=>(s.sceneId||s.writingId)===x.sourceId)?.title||x.sourceId)}</strong><p>${esc(x.note)}</p>${btn('edit-evidence','Edit evidence','edit',false,`data-id="${id}" data-evidence-id="${x.id}"`)}</article>`).join('')+btn('edit-evidence','Link evidence','plus',false,`data-id="${id}"`)));};actions['scene-details']=el=>sceneDetails(el.dataset.id);actions['edit-evidence']=el=>evidenceEditor(el.dataset.id,el.dataset.evidenceId);draftable.add('evidence');
const evidenceSubmit=extraSubmit;extraSubmit=function(form,data,m){const v=k=>String(data.get(k)||'').trim();if(form.dataset.form==='evidence'){const [sourceType,sourceId]=v('source').split(':');if(!sourceId)throw Error('Choose an existing fact or scene.');if(mutate('Kept evidence link',()=>{const n=node(m.id);n.evidenceLinks||=[];const previous=n.evidenceLinks.find(x=>x.id===m.evidenceId),record={id:m.evidenceId||W.uid(),sourceType,sourceId,bearing:v('bearing'),note:v('note')};if(previous)Object.assign(previous,record);else n.evidenceLinks.push(record);})){closeDialog();}return true;}return evidenceSubmit(form,data,m);};
function historicalSubject(kind,id){return kind==='character'?W.allCharacters(p()).find(c=>c.id===id):kind==='world'?W.allWorld(p()).find(w=>w.id===id):W.allConnections(p()).find(r=>r.id===id);}
function historicalRows(subject,kind){if(kind==='character')return [['changes',subject.changes],['lifeChanges',subject.lifeChanges],['stateCheckpoints',subject.stateCheckpoints],['prominence.changes',subject.prominence.changes],['prominence.checkpoints',subject.prominence.checkpoints]];if(kind==='world')return [['stateChanges',subject.stateChanges||[]],['faction.changes',subject.faction?.changes||[]],['faction.checkpoints',subject.faction?.checkpoints||[]]];return [['changes',subject.changes||[]]];}
history=function(kind,id){if(kind==='node'){consequenceDialog(W.events(p()).find(e=>e.nodeId===id)?.key||'');return;}const subject=historicalSubject(kind,id);if(!subject)return;modalData={kind:'history',subjectKind:kind,id};dialog('HISTORY',subject.name||subject.label,historicalRows(subject,kind).flatMap(([collection,rows])=>rows.map(x=>`<article class="history-row"><strong>${esc(x.status||x.block?.text||x.value||x.bond||human(collection.split('.').at(-1)))}</strong><small>${esc(momentOptions().find(y=>y[0]===(x.momentId||W.momentId(p(),x.at)))?.[1]||'Opening')}</small><p>${esc(x.reason||'')}</p>${btn('edit-historical-record','Edit change','edit',false,`data-kind="${kind}" data-id="${id}" data-collection="${collection}" data-record="${x.id}"`)}</article>`)).join('')||'<p>No timed changes yet.</p>',btn('new-history','Add change','plus',true,`data-kind="${kind}" data-id="${id}"`));};actions.history=el=>history(el.dataset.kind,el.dataset.id);
function editHistoricalRecord(kind,id,collection,recordId){const subject=historicalSubject(kind,id),rows=historicalRows(subject,kind).find(([name])=>name===collection)?.[1],x=rows?.find(x=>x.id===recordId);if(!x)return;modalData={kind:'historical-record',subjectKind:kind,id,collection,recordId};let body=select('At story moment','momentId',momentOptions().slice(1),x.momentId||W.momentId(p(),x.at));
 if(x.blocks){body+=x.blocks.map(b=>field(b.label||b.title||human(b.kind),'checkpoint-'+b.id,b.text,'','textarea')).join('');if(x.lifeStatus)body+=select('Life status','lifeStatus',[['alive','Alive'],['dead','Dead']],x.lifeStatus);}
 else if(kind==='character'&&collection==='changes'||collection==='faction.changes'){body+=select('Operation','operation',[['add','Gain piece'],['replace','Change piece'],['retire','Retire piece']],x.operation||(x.op==='develop'?'replace':x.op))+field('New words','text',x.block?.text||'','','textarea')+field('Detail','detail',x.block?.detail||'','','textarea');}
 else if(collection==='lifeChanges')body+=select('Life status','status',[['alive','Alive'],['dead','Dead']],x.status);
 else if(collection.startsWith('prominence.'))body+=field('Prominence','value',collection==='prominence.checkpoints'?x.value.value:x.value);
 else if(collection==='stateChanges')body+=field('New value','value',x.value)+select('Target','targetId',targetOptions(),x.targetId||'');
 else{const state=W.connectionState(p(),subject,x.momentId);body+=field('Connection','bond',x.bond??state.bond)+field('One wants','aWant',x.aWant??state.aWant)+field('Other wants','bWant',x.bWant??state.bWant)+field('Notes','notes',x.notes??state.notes,'','textarea')+connectionTermsFields({...state.terms,...x.terms});}
 body+=field('Reason','reason',x.reason||'','','textarea');dialog('REVISE A HISTORICAL RECORD',subject.name||subject.label,body,btn('remove-historical-record','Remove this change','trash')+submit('Keep revised change'),'historical-record');}
function connectionTermsFields(t={}){return disclosure('Terms at this moment',select('Membership','membership',['unspecified','member','associate','former','none'].map(x=>[x,human(x)]),t.membership||'unspecified')+field('Position','position',t.position||'')+select('Visibility','visibility',['open','concealed','contested'].map(x=>[x,human(x)]),t.visibility||'open')+field('First side’s tie','aTie',t.aTie||'')+field('Second side’s tie','bTie',t.bTie||'')+select('Supporting fact','factId',[['','None'],...p().world.filter(e=>e.type==='fact').map(e=>[e.id,e.name])],t.factId||'')+`<label><input name="active" type="checkbox" ${t.active!==false?'checked':''}> Active</label><label><input name="leadership" type="checkbox" ${t.leadership?'checked':''}> Leadership</label>`);}
const basicNewHistory=newHistory;newHistory=function(kind,id,key=''){basicNewHistory(kind,id,key);if(kind==='connection')$('#dialog .dialog-body').insertAdjacentHTML('beforeend',connectionTermsFields(W.connectionState(p(),historicalSubject(kind,id),key).terms));};actions['new-history']=el=>newHistory(el.dataset.kind,el.dataset.id);draftable.add('historical-record');
actions['edit-historical-record']=el=>editHistoricalRecord(el.dataset.kind,el.dataset.id,el.dataset.collection,el.dataset.record);
actions['remove-historical-record']=()=>{const m=modalData;if(mutate('Removed historical change',()=>{const subject=historicalSubject(m.subjectKind,m.id),keys=m.collection.split('.');let owner=subject;for(const key of keys.slice(0,-1))owner=owner[key];owner[keys.at(-1)]=owner[keys.at(-1)].filter(x=>x.id!==m.recordId);})){closeDialog();}};
const historicalSubmit=extraSubmit;extraSubmit=function(form,data,m){const v=k=>String(data.get(k)||'').trim(),terms=()=>({membership:v('membership'),position:v('position'),visibility:v('visibility'),aTie:v('aTie'),bTie:v('bTie'),factId:v('factId'),active:data.has('active'),leadership:data.has('leadership')});
 if(form.dataset.form==='historical-record'){if(!v('momentId'))throw Error('Choose a story moment.');if(mutate('Revised historical change',()=>{const subject=historicalSubject(m.subjectKind,m.id),x=historicalRows(subject,m.subjectKind).find(([name])=>name===m.collection)[1].find(x=>x.id===m.recordId);x.momentId=v('momentId');if(x.at)x.at=W.events(p()).find(e=>e.id===x.momentId).key;x.reason=v('reason');if(x.blocks){for(const b of x.blocks)b.text=v('checkpoint-'+b.id);if(data.has('lifeStatus'))x.lifeStatus=v('lifeStatus');}else if(data.has('operation')){const op=v('operation');if(m.subjectKind==='character'){x.op=op==='replace'?'develop':op;delete x.operation;}else x.operation=op;if(op==='retire')x.block=null;else{if(!x.block)throw Error('Restore this piece through a new change so its type and identity are explicit.');x.block.text=v('text');x.block.detail=v('detail');}}else if(data.has('status'))x.status=v('status');else if(data.has('value')){if(m.collection==='prominence.checkpoints')x.value={...x.value,value:v('value')};else x.value=v('value');if(data.has('targetId'))x.targetId=v('targetId');}else{for(const key of ['bond','aWant','bWant','notes'])x[key]=v(key);x.terms=terms();}}))closeDialog();return true;}
 if(form.dataset.form==='history-change'&&m.subjectKind==='connection'){if(!v('momentId'))throw Error('Choose a story moment.');if(mutate('Kept connection change',()=>{const r=historicalSubject('connection',m.id);r.changes||=[];const existing=r.changes.find(x=>x.momentId===v('momentId')),record={id:existing?.id||W.uid(),momentId:v('momentId'),bond:v('bond'),aWant:v('aWant'),bWant:v('bWant'),notes:v('notes'),reason:v('reason'),terms:terms()};if(existing)Object.assign(existing,record);else r.changes.push(record);}))closeDialog();return true;}
 return historicalSubmit(form,data,m);
};
const recoverSimpleDraft=actions['recover-draft'];
actions['recover-draft']=el=>{const d=p().drafts.find(x=>x.id===el.dataset.id);if(!d||d.form||d.kind==='scene'){recoverSimpleDraft(el);return;}const value=d.draft||{},cid=d.character||value.characterId||value.focus||'',id=value.id||value.entityId||value.targetId||'',moment=value.momentId||value.mid||d.preservedMomentId||'';let opened=true;
 if(d.kind==='name'&&person(cid))editCharacter(cid);
 else if(d.kind==='block'&&person(cid)){if(d.preservedMomentId)editChange(cid,value.id,W.events(p()).find(e=>e.id===d.preservedMomentId)?.key||'');else editBlock(cid,person(cid).blocks.some(b=>b.id===value.id)?value.id:'',value.kind||'custom');}
 else if(['connection','en-tie'].includes(d.kind))editConnection(p().connections.some(r=>r.id===id)?id:'');
 else if(['entity','en-faction-block'].includes(d.kind)){if(d.kind==='entity')editWorld(p().world.some(w=>w.id===id)?id:'');else if(p().world.some(w=>w.id===(value.entityId||id)))factionBlock(value.entityId||id,value.blockId||value.id);else opened=false;}
 else if(['life','entity-state','connection-change'].includes(d.kind))newHistory(d.kind==='life'?'character':d.kind==='entity-state'?'world':'connection',cid||d.entity||d.connection||id,moment);
 else if(d.kind==='earlier-opening'&&person(cid))earlierSelf(cid);
 else if(d.kind==='en-role')plotRole(value.plotId,cid);
 else if(d.kind==='evidence')evidenceEditor(d.thread||value.threadId,value.id);
 else opened=false;
 if(!opened){modalData={kind:'legacy-draft',id:d.id};dialog('RECOVERED WORK IN PROGRESS',human(d.kind),'<p>This unfinished record is preserved separately. Edit the original fields here, or export it for reference; your accepted story stays intact.</p>'+legacyDraftFields(value),submit('Keep recovered draft'),'legacy-draft');return;}
 const form=$('#dialog form');if(!form)return;const mapped={...value,label:value.label??value.title,pinned:value.pinned??value.locked,lifeStatus:value.lifeStatus??value.status,momentId:moment,preservedLabel:value.preservedLabel||'',earlierLabel:value.earlierLabel||''};for(const field of form.elements){if(!field.name||!(field.name in mapped))continue;const raw=mapped[field.name];if(field.type==='checkbox')field.checked=!!raw;else if(typeof raw==='string')field.value=raw;}
 activeFormDraft=d.id;captureFormDraft();
};
function legacyDraftFields(value,prefix=''){return Object.entries(value).filter(([key])=>!['id','sources','sourceHash','parentHash','ensembleSnapshot','blockSources'].includes(key)).map(([key,item])=>{const path=prefix?prefix+'.'+key:key;if(typeof item==='string'||typeof item==='number')return field(human(key),path,String(item),'',typeof item==='number'?'number':'textarea');if(typeof item==='boolean')return `<label class="check-chip"><input type="checkbox" name="${esc(path)}" ${item?'checked':''}>${esc(human(key))}</label>`;if(item&&typeof item==='object')return disclosure(human(key),legacyDraftFields(item,path));return '';}).join('');}
const recoveredDraftSubmit=extraSubmit;extraSubmit=function(form,data,m){if(form.dataset.form==='legacy-draft'){if(mutate('Kept recovered unfinished draft',()=>{const d=p().drafts.find(x=>x.id===m.id);for(const field of form.elements){if(!field.name)continue;const keys=field.name.split('.');if(keys.some(k=>['__proto__','prototype','constructor'].includes(k)))throw Error('Unsupported draft field.');let owner=d.draft;for(const key of keys.slice(0,-1))owner=owner[key];const last=keys.at(-1);owner[last]=field.type==='checkbox'?field.checked:field.type==='number'?Number(field.value):field.value;}d.updatedAt=new Date().toISOString();})){closeDialog();}return true;}return recoveredDraftSubmit(form,data,m);};

function applySceneDetails(n,data){const v=k=>String(data.get(k)||'').trim();for(const k of craftFields)n[k]=v(k);n.sceneKind=v('sceneKind');n.thread=v('thread');n.povId=v('povId');n.focus=n.povId;n.beats=v('beats').split('\n').filter(Boolean);n.ensemble=W.allCharacters(p()).filter(c=>v('role-'+c.id)).map(c=>({...n.ensemble?.find(x=>x.id===c.id),id:c.id,role:v('role-'+c.id)}));n.cast=[...new Set([...n.ensemble.map(x=>x.id),n.povId].filter(Boolean))];n.miceLinks=W.allNodes(p()).filter(t=>t.type!=='B'&&v('thread-'+t.id)).map(t=>({...n.miceLinks?.find(x=>x.miceId===t.id),miceId:t.id,edge:v('thread-'+t.id),role:v('thread-'+t.id)}));n.parent=v('parent');n.extraParents=data.getAll('extraParents').map(id=>n.extraParents?.find(x=>x.id===id)||{id,hash:''});n.openSceneId=v('openSceneId');n.closeSceneId=v('closeSceneId');}

// Write and Refine share the same selected manuscript moment.
function readingView(){
 const moments=visibleWritingMoments(),hasDraft=moments.some(e=>momentProse(e).trim()),mode=ui.readContent||(hasDraft?'draft':'plan');
 const text=e=>mode==='draft'?momentProse(e):(e.edge==='close'?e.node.closing:e.node.opening)||'';
 const readable=moments.filter(e=>text(e).trim());
 return heading('THE STORY WORKBENCH','Read your story',mode==='plan'?'Read the openings, beats, and closings from your plan.':'Read your draft prose in manuscript order.')+plotToolbar()+`<div class="reading-controls" role="group" aria-label="Reading content">${[['plan','Plan'],['draft','Draft']].map(([id,label])=>`<button class="btn ${mode===id?'primary':''}" ${act('reading-content',id)} aria-pressed="${mode===id}">${label}</button>`).join('')}</div><article class="continuous-manuscript"><h1>${esc(p().title)}</h1>${readable.map(e=>`<section data-reading-moment="${esc(e.key)}"><button class="text-btn" ${act(mode==='plan'?'refine-node':'write-node',e.node.id,`data-edge="${e.edge}"`)}>Edit ${esc(name(e.node))} · ${momentLabel(e)}</button><h2>${esc(name(e.node))}${e.edge==='close'?' · Closing':''}</h2><div class="manuscript-prose">${esc(text(e))}</div></section>`).join('')||`<div class="reading-empty"><p>${mode==='draft'?'No draft prose in this view yet. Your plan is available in Plan.':'No planned text in this view yet. Add an opening, beat, or closing in Outline or Refine.'}</p>${mode==='draft'?btn('reading-content','Read the plan','book',false,'data-id="plan"'):''}</div>`}</article>`;
}
actions['reading-content']=el=>{finishEdit();ui.readContent=el.dataset.id;render();};
function momentProse(e){return (e.edge==='close'?e.node.closingProse:e.node.prose)||'';}
function visibleWritingMoments(){const ids=new Set(visibleNodes().map(n=>n.id));return W.readingMoments(p()).filter(e=>ids.has(e.node.id));}
function selectedWritingMoment(moments){const e=moments.find(e=>e.node.id===ui.selected&&e.edge===(ui.writeEdge||'open'))||moments.find(e=>e.node.id===ui.selected)||moments[0];ui.selected=e.node.id;ui.writeEdge=e.edge;return e;}
function momentNavigation(moments,selected,action){return `<nav class="scene-list moment-navigation" aria-label="Openings, beats, and closings in manuscript order">${moments.map(e=>`<button class="${e.key===selected.key?'active':''}" ${act(action,e.node.id,`data-edge="${e.edge}"`)} ${e.key===selected.key?'aria-current="true"':''}><span class="ordinal">${e.edge==='close'?'↳':e.node.type==='B'?'·':e.node.type}</span><span>${esc(name(e.node))}<small>${momentLabel(e)}</small></span></button>`).join('')}</nav>`;}
function momentSwitcher(e,action){return e.node.type==='B'?'':`<div class="moment-switcher" role="group" aria-label="Thread opening or closing">${['open','close'].map(edge=>`<button class="btn ${edge===e.edge?'primary':''}" ${act(action,e.node.id,`data-edge="${edge}"`)} aria-pressed="${edge===e.edge}">${edge==='close'?'Closing':'Opening'}</button>`).join('')}</div>`;}
function refining(){
 const moments=visibleWritingMoments();
 if(!moments.length)return empty('Make room for a story.','Add a thread or beat to start refining.',btn('new-piece','Add a piece','plus'),'edit');
 const e=selectedWritingMoment(moments),n=e.node,closing=e.edge==='close',craft=closing?n.closingCraft||{cast:[...n.cast],worldIds:[]}:n;
 const questions=refineQuestions(n,e.edge),attrs=`data-id="${n.id}" data-edge="${e.edge}"`;
 const fields=questions.map(([key,label,hint])=>`<label class="field"><span>${esc(label)}</span><textarea data-inline="prompt" ${attrs} data-field="${key}" aria-label="${esc(label)}" placeholder="${esc(hint)}">${esc(craft.refinement?.[key]||'')}</textarea></label>`).join('');
 const legacy=disclosure('Additional craft notes',`<p class="refine-save-note">Optional notes for the scene or scenes carrying this piece.</p>`+craftFields.map(k=>field(human(k),k,craft[k]||'','','textarea')).join('')+field('Smaller developments · one per line','beats',(craft.beats||[]).join('\n'),'','textarea')+(craft.thread?field('Previous grouping label','thread',craft.thread):'')+(craft.sceneKind&&craft.sceneKind!=='open'?field('Previous scene approach','sceneKind',craft.sceneKind):''));
 const notes=legacy.replace(/<(input|textarea|select)\b/g,`<$1 data-inline="craft" ${attrs}`);
 const evidence=n.type==='I'?disclosure('Evidence and interpretation',(n.evidenceLinks||[]).map(x=>`<article class="history-row"><strong>${esc(x.bearing)} · ${esc(p().world.find(w=>w.id===x.sourceId)?.name||W.allNodes(p()).find(s=>[s.id,s.sceneId,s.writingId].includes(x.sourceId))?.title||x.sourceId)}</strong><p>${esc(x.note)}</p>${btn('edit-evidence','Edit evidence','edit',false,`data-id="${n.id}" data-evidence-id="${x.id}"`)}</article>`).join('')+btn('edit-evidence','Link evidence','plus',false,`data-id="${n.id}"`)):'';
 return `<section class="refine-workspace writing-layout" aria-label="Refine story moments">${momentNavigation(moments,e,'refine-node')}<article class="refine-piece manuscript" data-refine-moment="${esc(e.key)}"><div class="eyebrow">${esc(W.TYPES[n.type].name).toUpperCase()} · ${momentLabel(e).toUpperCase()} · REFINE</div>${n.type==='C'?`<input class="draft-title" data-inline="node" data-id="${n.id}" data-field="title" value="${esc(W.editableTitle(p(),n))}" aria-label="Refine title" placeholder="Name this thread…" maxlength="1000">${threadEndpoint(n,closing?'close':'open','refine')}`:`<input class="draft-title" data-inline="node" data-id="${n.id}" data-field="title" value="${esc(n.title)}" placeholder="Untitled piece" aria-label="Refine title" maxlength="1000">${n.type!=='B'?threadEndpoint(n,closing?'close':'open','refine'):beatStateChanges(n)}`}<div class="piece-change-tools">${btn('consequences','Record a change','change',false,`data-id="${e.key}"`)}</div>${momentSwitcher(e,'refine-node')}<label class="field refine-plan"><span>${esc(refinePlanQuestion(n,e.edge))}</span><textarea data-inline="node" data-id="${n.id}" data-field="${closing?'closing':'opening'}" aria-label="${closing?'Closing':n.type==='B'?'Beat':'Opening'} plan" placeholder="${esc(closing?W.TYPES[n.type].closing:W.TYPES[n.type].opening)}">${esc(closing?n.closing:n.opening)}</textarea></label><p class="refine-save-note">${n.type==='B'?'A beat can be an intermediate step in a larger change. It can advance several threads.':'A thread can unfold across several scenes. Refine what this '+(closing?'closing resolves':'opening sets in motion')+'.'} Changes save as you go.</p><div class="refine-essentials">${refinePeople(n,e.edge,craft)}${refineConnections(n,e.edge,craft)}</div><div class="refine-questions">${fields}</div><form class="refine-form" aria-label="Additional craft notes">${notes}</form>${evidence}${WORKSPACE_FEATURES.drafting?`<div class="draft-refine">${btn('write-node','Write this '+(closing?'closing':n.type==='B'?'beat':'opening'),'write',false,`data-id="${n.id}" data-edge="${e.edge}"`)}</div>`:''}</article></section>`;
}
function openRefine(el){
 finishEdit();const n=node(el.dataset.id);if(!n)return;
 ui.writeEdge=el.dataset.edge||(ui.selected===n.id?ui.writeEdge:'open')||'open';ui.selected=n.id;ui.mode='refine';ui.detailsOpen=false;
 // A direct link must reveal its target even when the previous view was filtered.
 if(!visibleNodes().some(x=>x.id===n.id)){branchFocus='';storyFilter='';onlyReview=false;ui.plot='';}
 navigate('outline');$('.refine-piece .draft-title')?.focus({preventScroll:true});
}
actions['refine-node']=openRefine;
actions['scene-details']=openRefine;
const pieceInlineUpdate=inlineUpdate;
inlineUpdate=function(el){
 if(!['craft','prompt'].includes(el.dataset.inline)){pieceInlineUpdate(el);return;}
 const n=node(el.dataset.id),closing=el.dataset.edge==='close';if(!n)return;
 if(!editBefore){editBefore=W.copy(workspace);editLabel='Refined '+(closing?'closing':'piece');}
 const target=closing?(n.closingCraft||={cast:[...n.cast],worldIds:[]}):n;
 if(el.dataset.inline==='prompt')(target.refinement||={})[el.dataset.field]=el.value;
 else target[el.name]=el.name==='beats'?el.value.split('\n').filter(Boolean):el.value;
 clearTimeout(saveTimer);saveTimer=setTimeout(save,250);
};
document.addEventListener('submit',e=>{if(e.target.matches('.refine-form')){e.preventDefault();finishEdit();}});

function refinePlanQuestion(n,edge){
 const questions={M:['What unfamiliar world or situation do they enter?','How do they leave, belong, or change their relationship to this world?'],I:['What question does this thread ask?','What answer does this thread arrive at?'],C:['What belief, desire, or dissatisfaction starts this character’s change?','What choice shows who this character has become?'],E:['What disruption sets this thread in motion?','How is the disruption resolved, or a new balance established?'],B:['What happens in this beat?']};return questions[n.type][edge==='close'?1:0];
}
function refineQuestions(n,edge){
 if(n.type==='B')return [['change','What changes because of this beat?','A new fact, a decision, a shift in power, or a change in a relationship.'],['whyNow','Why does this happen here?','What brings it about, and what does it make possible next?'],['readerEffect','What should the reader notice or feel?','You can reveal, complicate, reinforce, or withhold something.']];
 if(edge==='close')return [['earned',({M:'What makes this departure or belonging earned?',I:'What evidence makes the answer convincing?',C:'What earlier choices make this change believable?',E:'What actions and consequences make this resolution earned?'})[n.type],'Point to earlier developments that prepare this outcome.'],['consequence','What remains changed, lost, or unresolved?','The cost, the lasting effect, or something deliberately left open.'],['readerEffect','How does this pay off or reframe the opening?','What should the reader recognize when looking back?']];
 return [['onPage',({M:'How does the reader experience the threshold?',I:'How does the reader encounter the question?',C:'How is this starting state shown through a choice or behavior?',E:'How does the reader experience the disruption?'})[n.type],'Describe the action, image, exchange, or discovery that brings it onto the page.'],['pressure',({M:'What makes leaving or belonging difficult?',I:'What makes the answer difficult to find?',C:'What puts pressure on this way of thinking or living?',E:'What prevents things from being put right immediately?'})[n.type],'This pressure may develop over several scenes.'],['readerPromise','What possibility does this invite the reader to anticipate?','The outcome they hope for, fear, or want to understand.']];
}
function refineTarget(id,edge,create=false){const n=node(id);if(!n)return null;if(edge!=='close')return n;if(create)n.closingCraft||={cast:[...n.cast],worldIds:[]};return n.closingCraft||{cast:[...n.cast],worldIds:[]};}
function refinePeople(n,edge,c){const attrs=`data-id="${n.id}" data-edge="${edge}"`;return `<section class="refine-relations"><div class="section-head"><h3>People involved</h3>${btn('refine-add-person','Add someone','plus',false,attrs)}</div><div class="refine-people">${c.cast.map(id=>W.allCharacters(p()).find(x=>x.id===id)).filter(Boolean).map(person=>`<div class="refine-person">${avatar(person)}<strong>${esc(person.name)}</strong><select aria-label="Role for ${esc(person.name)}" data-refine-role="${person.id}" ${attrs}>${opts([['present','Involved'],['assist','Supports'],['oppose','Opposes'],['complicate','Complicates'],['witness','Witnesses']],c.ensemble?.find(x=>x.id===person.id)?.role||'present')}</select>${ib('refine-remove-person',n.id,'close','Remove '+person.name,`data-edge="${edge}" data-person="${person.id}"`)}</div>`).join('')||'<p class="refine-save-note">Add only the people who matter here.</p>'}</div><label class="refine-viewpoint">Viewpoint <select aria-label="Viewpoint" data-refine-pov="true" ${attrs}>${opts([['','No viewpoint chosen'],...c.cast.map(id=>W.allCharacters(p()).find(x=>x.id===id)).filter(Boolean).map(c=>[c.id,c.name])],c.povId||c.focus||'')}</select></label></section>`;}
const refineLinkLabels={open:'Opens the thread',advance:'Advances the thread',close:'Closes the thread',parent:'Follows from',extra:'Also follows from',openSceneId:'Opening happens in',closeSceneId:'Closing happens in'};
function refineLinkRows(c){return [...(c.miceLinks||[]).map(x=>({kind:x.edge||x.role,id:x.miceId})),...(c.parent?[{kind:'parent',id:c.parent}]:[]),...(c.extraParents||[]).map(x=>({kind:'extra',id:x.id})),...['openSceneId','closeSceneId'].filter(k=>c[k]).map(k=>({kind:k,id:c[k]}))];}
function refineConnections(n,edge,c){return `<section class="refine-relations"><div class="section-head"><h3>Connected pieces</h3>${btn('refine-add-link','Link a piece','plus',false,`data-id="${n.id}" data-edge="${edge}"`)}</div><div class="refine-links">${refineLinkRows(c).map(x=>{const target=W.allNodes(p()).find(n=>[n.id,n.sceneId,n.writingId].includes(x.id));return `<div class="refine-link"><div><small>${esc(refineLinkLabels[x.kind]||x.kind)}</small><strong>${esc(target?name(target):x.id)}</strong></div>${ib('refine-remove-link',n.id,'close','Remove link: '+(target?name(target):x.id),`data-edge="${edge}" data-link-kind="${x.kind}" data-target="${esc(x.id)}"`)}</div>`;}).join('')||'<p class="refine-save-note">Connect this piece to the threads it develops or the pieces it depends on.</p>'}</div></section>`;}
function refinePicker(kind,el){finishEdit();modalData={kind:'refine-picker',picker:kind,id:el.dataset.id,edge:el.dataset.edge};const n=node(modalData.id);dialog(kind==='person'?'PEOPLE INVOLVED':'CONNECTED PIECES',kind==='person'?'Add someone':'Link a piece',(kind==='link'?select('How are they connected?','refine-link-kind',[['advance','This piece advances a thread'],['open','This piece opens a thread'],['close','This piece closes a thread'],['parent','This piece follows from another piece'],['extra','This piece also follows from another piece'],...(n.type!=='B'?[['openSceneId','This thread’s opening happens in another piece'],['closeSceneId','This thread’s closing happens in another piece']]:[])],'advance'):'')+`<input id="refine-picker-search" aria-label="${kind==='person'?'Find a person':'Find a piece'}" placeholder="Search by name…"><div id="refine-picker-results" class="refine-picker-results"></div>`);renderRefinePicker();requestAnimationFrame(()=>$('#refine-picker-search')?.focus());}
function renderRefinePicker(){const m=modalData,c=refineTarget(m.id,m.edge),q=($('#refine-picker-search')?.value||'').toLocaleLowerCase(),kind=$('[name=refine-link-kind]')?.value||'';const rows=m.picker==='person'?W.allCharacters(p()).filter(x=>!c.cast.includes(x.id)):W.allNodes(p()).filter(x=>(x.id!==m.id||['open','advance','close'].includes(kind))&&(!['open','advance','close'].includes(kind)||x.type!=='B'));const filtered=rows.filter(x=>((x.name||name(x))+' '+(x.title||'')).toLocaleLowerCase().includes(q));$('#refine-picker-results').innerHTML=filtered.slice(0,20).map(x=>`<button class="refine-picker-result" ${act('refine-pick',x.id)}>${m.picker==='person'?avatar(x):`<span class="piece-mark color-${W.TYPES[x.type].color}">${x.type}</span>`}<span>${esc(x.name||name(x))}</span>${icon('plus')}</button>`).join('')||'<p class="refine-save-note">No matching '+(m.picker==='person'?'people':'pieces')+'.</p>';}
actions['refine-add-person']=el=>refinePicker('person',el);
actions['refine-add-link']=el=>refinePicker('link',el);
actions['refine-pick']=el=>{const m={...modalData},kind=$('[name=refine-link-kind]')?.value,id=el.dataset.id;const ok=mutate(m.picker==='person'?'Added person':'Linked piece',()=>{const c=refineTarget(m.id,m.edge,true);if(m.picker==='person'){if(!c.cast.includes(id))c.cast.push(id);return;}const target=W.allNodes(p()).find(n=>n.id===id),sceneId=target.sceneId||target.id;if(['open','advance','close'].includes(kind)){c.miceLinks||=[];const link=c.miceLinks.find(x=>x.miceId===id);if(link)Object.assign(link,{edge:kind,role:kind});else c.miceLinks.push({miceId:id,edge:kind,role:kind});}else if(kind==='extra'){c.extraParents||=[];if(!c.extraParents.some(x=>x.id===sceneId))c.extraParents.push({id:sceneId,hash:''});}else c[kind]=sceneId;},{notify:false});if(ok)closeDialog();};
actions['refine-remove-person']=el=>mutate('Removed person',()=>{const c=refineTarget(el.dataset.id,el.dataset.edge,true),id=el.dataset.person;c.cast=c.cast.filter(x=>x!==id);c.ensemble=(c.ensemble||[]).filter(x=>x.id!==id);if(c.povId===id)c.povId='';if(c.focus===id)c.focus='';},{notify:false});
actions['refine-remove-link']=el=>mutate('Removed link',()=>{const c=refineTarget(el.dataset.id,el.dataset.edge,true),kind=el.dataset.linkKind,id=el.dataset.target;if(['open','advance','close'].includes(kind))c.miceLinks=(c.miceLinks||[]).filter(x=>x.miceId!==id);else if(kind==='extra')c.extraParents=(c.extraParents||[]).filter(x=>x.id!==id);else c[kind]='';},{notify:false});
document.addEventListener('input',e=>{if(e.target.id==='refine-picker-search')renderRefinePicker();});
document.addEventListener('change',e=>{const el=e.target;if(el.name==='refine-link-kind'){renderRefinePicker();return;}if(!el.dataset.refineRole&&!el.dataset.refinePov)return;mutate('Updated people',()=>{const c=refineTarget(el.dataset.id,el.dataset.edge,true);if(el.dataset.refinePov){c.povId=el.value;c.focus=el.value;}else{c.ensemble||=[];const role=c.ensemble.find(x=>x.id===el.dataset.refineRole);if(role)role.role=el.value;else c.ensemble.push({id:el.dataset.refineRole,role:el.value});}},{rerender:false,notify:false});});

let plotScrollObserver;
function updatePlotOverflow(nav){const wrapper=nav.parentElement;wrapper.classList.toggle('can-scroll-left',nav.scrollLeft>2);wrapper.classList.toggle('can-scroll-right',nav.scrollLeft+nav.clientWidth<nav.scrollWidth-2);ui.plotScrollLeft=nav.scrollLeft;}
function syncPlotToolbar(){
 plotScrollObserver?.disconnect();const nav=$('.plot-scroll nav');if(!nav)return;
 nav.scrollLeft=ui.plotScrollLeft||0;updatePlotOverflow(nav);
 nav.addEventListener('scroll',()=>updatePlotOverflow(nav),{passive:true});
 plotScrollObserver=new ResizeObserver(()=>updatePlotOverflow(nav));plotScrollObserver.observe(nav);
}
/* A temporary, nonmodal shelf: the outline remains a live drop destination. */
function drawerForNode(id){return W.drawerEntries(p()).find(a=>a.nodes.some(n=>n.id===id));}
function drawerButton(){const count=W.drawerEntries(p()).length;return `<button class="tray-drawer" data-action="toggle-drawer" data-drop="drawer" aria-expanded="${!!ui.drawerOpen}" aria-controls="piece-drawer" aria-label="Drawer${count?', '+count+' stored '+(count===1?'piece':'pieces'):''}" title="Set pieces aside · drag here or open Drawer">${icon('drawer')}<small>Drawer</small>${count?`<span class="drawer-count">${count}</span>`:''}</button>`;}
function drawerPanel(){if(!ui.drawerOpen)return '';const entries=W.drawerEntries(p());return `<aside id="piece-drawer" class="piece-drawer" role="region" aria-label="Temporary story pieces" tabindex="-1"><header><div><strong>Drawer</strong><span>${entries.length} ${entries.length===1?'piece':'pieces'} set aside</span></div>${ib('toggle-drawer','','close','Close Drawer')}</header><p>Drag a piece back into the outline, or put it back where it was.</p><div class="drawer-list">${entries.map(a=>{const n=a.nodes[0],t=W.TYPES[n.type];return `<article class="drawer-card color-${t.color}" data-drawer-id="${esc(a.id)}" style="${colorStyle(n.color,t.color)}"><div class="drawer-card-heading"><button class="grip" draggable="true" data-drag="drawer" data-drag-id="${esc(a.id)}" ${act('place-drawer',a.id)} aria-label="Move ${esc(a.title)} from Drawer" title="Drag into the outline · click for placement options">⠿</button><span class="piece-mark">${n.type==='B'?'+':n.type}</span><strong>${esc(a.title)}</strong></div>${n.opening?`<p>${esc(n.opening)}</p>`:''}<footer><span>${t.name}${a.nodes.length>1?' · '+(a.nodes.length-1)+' nested '+(a.nodes.length===2?'piece':'pieces'):''}</span><button class="text-btn" ${act('return-drawer',a.id)}>${icon('undo')}Put back</button></footer></article>`;}).join('')||'<div class="drawer-empty">A little room to experiment.<br>Drop a thread or beat onto Drawer to keep it here.</div>'}</div><div class="drawer-drop drop-target" data-drop="drawer">Drop a piece here to set it aside</div></aside>`;}
function positionDrawer(){const panel=$('#piece-drawer'),button=$('.tray-drawer'),tray=$('.tray');if(!panel||!button||!tray)return;const r=button.getBoundingClientRect(),t=tray.getBoundingClientRect();panel.style.left=Math.max(12,Math.min(innerWidth-panel.offsetWidth-12,r.right-panel.offsetWidth))+'px';panel.style.bottom=Math.max(12,innerHeight-t.top+10)+'px';panel.style.maxHeight=Math.max(100,t.top-24)+'px';}
window.addEventListener('resize',positionDrawer);
function stashPiece(id){const n=node(id);if(!n)return;if(mutate('Set aside '+name(n)+' in Drawer',pr=>W.stashNode(pr,id))&&$('#dialog').open)closeDialog();}
function returnPiece(id,anchor,where){const ok=mutate('Returned piece from Drawer',pr=>{const root=W.returnFromDrawer(pr,id,anchor,where);ui.selected=root;ui.snap=root;ui.drawerOpen=false;ui.mode='outline';ui.plot='';branchFocus='';storyFilter='';onlyReview=false;let ancestor=node(root)?.parentId;while(ancestor){ui.folded.delete(ancestor);ancestor=node(ancestor)?.parentId;}ui.folded.delete(anchor);});if(ok){if($('#dialog').open)closeDialog();requestAnimationFrame(()=>$(`[data-node="${CSS.escape(ui.selected)}"]`)?.scrollIntoView({block:'center',behavior:'smooth'}));}return ok;}
actions['toggle-drawer']=()=>{finishEdit();ui.drawerOpen=!ui.drawerOpen;if(ui.drawerOpen){$('#toast').classList.remove('visible');ui.mode='outline';ui.inspectorMode=ui.inspectorMode==='full'?'side':ui.inspectorMode;ui.detailsOpen=false;}render();(ui.drawerOpen?$('#piece-drawer'):$('.tray-drawer'))?.focus({preventScroll:true});};
actions['stash-node']=el=>stashPiece(el.dataset.id);
actions['return-drawer']=el=>returnPiece(el.dataset.id);
actions['place-drawer']=el=>{const a=W.drawerEntries(p()).find(a=>a.id===el.dataset.id);if(!a)return;modalData={kind:'place-drawer',id:a.id};dialog('BRING IT BACK',a.title,select('Destination','anchor',[['','The outermost outline'],...W.ordered(p()).map(x=>[x.node.id,'— '.repeat(Math.min(x.depth,6))+name(x.node)])],'')+select('Position','where',[['inside','Inside, at the end'],['before','Before this piece'],['after','After this piece']],'inside'),submit('Place in outline'),'place-drawer');};
const drawerSubmit=extraSubmit;extraSubmit=function(form,data,m){if(form.dataset.form==='place-drawer'){returnPiece(m.id,String(data.get('anchor')||''),String(data.get('where')||'inside'));return true;}return drawerSubmit(form,data,m);};

function threadPlanFields(n,edge='open',view='outline'){
 const labels=W.THREAD_FIELDS[n.type];if(!labels)return '';
 const plan=W.threadPlan(n),field=(key,value,outcomeId='')=>`<label class="thread-word"><span>${esc(labels[key])}</span><input data-thread-field="${key}" data-id="${n.id}" data-outcome="${outcomeId}" value="${esc(value)}" placeholder="${esc(labels[key+'Hint'])}" maxlength="1000" aria-label="${esc(W.TYPES[n.type].name+' '+labels[key])}${outcomeId?' · additional outcome':''}" style="--state-chars:${Math.min(36,Math.max(14,value.length+1))}ch">${outcomeId?`<button type="button" class="arc-state-options" ${act('thread-remove-outcome',n.id,`data-outcome="${outcomeId}"`)} aria-label="Remove additional ${esc(labels.to.toLowerCase())}">${icon('close')}</button>`:''}</label>`;
 return `<div class="thread-plan-fields color-${W.TYPES[n.type].color}" role="group" aria-label="${W.TYPES[n.type].name} ${edge==='open'?'opening':'closing'} fields">${edge==='open'?field('focus',plan.focus)+field('from',plan.from):field('to',plan.to)+plan.outcomes.map(x=>field('to',x.text,x.id)).join('')+`<button type="button" class="arc-fork" ${act('thread-add-outcome',n.id)} aria-label="Add another ${esc(labels.to.toLowerCase())}" title="Add another outcome">${icon('plus')}</button>`}${view==='outline'&&!(edge==='open'?n.opening:n.closing)?`<button type="button" class="text-btn thread-note-launch" ${act('reveal-thread-note',n.id,`data-edge="${edge}"`)} aria-label="Add ${edge==='open'?'opening':'closing'} note">${icon('plus')}Note</button>`:''}</div>`;
}
function recordedStates(n,edge){
 const changes=W.recordedThreadStates(p(),n,edge);if(!changes.length)return '';
 return `<div class="thread-recorded-states" role="group" aria-label="Recorded states at ${edge==='open'?'opening':'closing'}">${changes.map(x=>`<div class="recorded-state"><span class="recorded-state-who">${esc(x.subject)}</span><span class="arc-state-label">${esc(human(x.label))}</span><input data-piece-state="${esc(x.id)}" data-id="${n.id}" data-edge="${edge}" value="${esc(x.value)}" aria-label="${esc(x.subject+' '+human(x.label))} at ${edge==='open'?'opening':'closing'}" title="${esc(x.value)}" maxlength="1000" style="--state-chars:${Math.min(36,Math.max(12,x.value.length+1))}ch">${x.canFork?`<button type="button" class="arc-fork" ${act('fork-piece-state',n.id,`data-change="${esc(x.id)}" data-edge="${edge}"`)} aria-label="Fork ${esc(x.subject+' '+human(x.label))}" title="Keep this state and add another">${icon('plus')}</button>`:''}</div>`).join('')}</div>`;
}
function threadEndpoint(n,edge,view='outline'){
 return (n.type==='C'?characterArcHeader(n,edge==='open'?'from':'to',view):threadPlanFields(n,edge,view))+recordedStates(n,edge);
}
function threadLinksLine(n){
 const context=W.openThreadContext(p(),n);if(!context.links.length)return '';
 const links=context.links;
 return `<div class="thread-links-line"><span>Advances</span>${links.map(t=>`<button type="button" class="thread-link-chip color-${W.TYPES[t.type].color}" ${act('jump-thread',t.id)} title="${esc(name(t))}"><b>${t.type}</b><span>${esc(W.editableTitle(p(),t)||W.TYPES[t.type].name+' thread')}</span></button>`).join('')}<button type="button" class="text-btn" ${act('thread-links',n.id)} aria-label="Choose threads advanced by this ${n.type==='B'?'beat':'thread'}">${icon('plus')}${links.length?'':'Threads'}</button>${n.type==='B'&&context.stillOpen.length?`<span class="still-open" title="${esc(context.stillOpen.map(t=>name(t)).join(' · '))}">${context.stillOpen.map(t=>t.type).join(' + ')} still open</span>`:''}</div>`;
}
actions['reveal-thread-note']=el=>{const root=$(`[data-node="${CSS.escape(el.dataset.id)}"]`),area=root?.querySelector(el.dataset.edge==='open'?':scope > .node-promise textarea':':scope > .closing textarea');if(!area)return;(el.dataset.edge==='open'?area.parentElement:area).classList.remove('is-empty-note');area.focus();fit(area);el.hidden=true;};
actions['jump-thread']=el=>{ui.folded.delete(el.dataset.id);ui.selected=el.dataset.id;render();$(`[data-node="${CSS.escape(el.dataset.id)}"]`)?.scrollIntoView({block:'center',behavior:'smooth'});};
actions['thread-links']=el=>{
 const n=node(el.dataset.id),context=W.openThreadContext(p(),n),selected=context.links.length?context.links.map(t=>t.id):n.type==='B'&&context.owner?[context.owner.id]:[];
 const all=W.ordered(p()).map(x=>x.node).filter(t=>t.type!=='B'&&t.id!==n.id),open=new Set(context.ancestors.map(t=>t.id));modalData={kind:'thread-links',id:n.id};
 const options=items=>items.map(t=>`<label class="thread-link-option"><input type="checkbox" name="threads" value="${t.id}" ${selected.includes(t.id)?'checked':''}><span class="piece-mark color-${W.TYPES[t.type].color}">${t.type}</span><span>${esc(name(t))}</span></label>`).join('');
 dialog('ONE MOMENT, SEVERAL THREADS','What does this advance?',`<p class="help">Choose any threads this ${n.type==='B'?'beat':'thread'} moves forward. Its position stays the same; the surrounding threads remain open.</p>${open.size?`<div class="field-label">Open around this piece</div>${options(all.filter(t=>open.has(t.id)))}`:''}${all.some(t=>!open.has(t.id))?disclosure('Other threads',options(all.filter(t=>!open.has(t.id))),!open.size):''}`,submit('Keep thread links'),'thread-links');
};
actions['add-beat-here']=el=>{const n=W.node('B',el.dataset.id);n.plotIds=ui.plot?[ui.plot]:[...(node(el.dataset.id)?.plotIds||[])];if(mutate('Added a beat',()=>{p().nodes.push(n);ui.selected=n.id;ui.folded.delete(el.dataset.id);})){actions['thread-links']({dataset:{id:n.id}});}};
actions['thread-add-outcome']=el=>{let id;if(mutate('Added thread outcome',()=>{id=W.addThreadOutcome(node(el.dataset.id));},{notify:false}))requestAnimationFrame(()=>$(`[data-thread-field][data-id="${el.dataset.id}"][data-outcome="${id}"]`)?.focus());};
actions['thread-remove-outcome']=el=>mutate('Removed thread outcome',()=>W.removeThreadOutcome(node(el.dataset.id),el.dataset.outcome));
actions['fork-piece-state']=el=>{
 const n=node(el.dataset.id),edge=el.dataset.edge||'open',state=W.changeStateAt(p(),el.dataset.change,n.id+':'+edge);if(!state.block)return;
 modalData={kind:'fork-piece-state',id:n.id,changeId:el.dataset.change,edge};
 dialog('ONE STATE, MORE THAN ONE OUTCOME','Add a parallel state',`<p class="help">Keep <strong>${esc(state.value)}</strong> and add another ${esc(state.block.label||state.block.title||human(state.block.kind))} at this moment. Both remain part of the story.</p>`+field('Additional state','value','','e.g. Wanted by the law'),submit('Add state'),'fork-piece-state');
};
function pieceStateSources(n,edge){
 const key=n.id+':'+edge,out=[];
 for(const c of p().characters)for(const b of W.stateAt(p(),c,key))out.push({id:'block:'+c.id+':'+b.id,label:c.name+' · '+(b.label||kind(b.kind).label),value:b.text,fork:true});
 for(const w of p().world){out.push({id:'world:'+w.id,label:w.name+' · '+(w.stateLabel||'State'),value:W.worldState(p(),w,key).value});if(w.type==='group')for(const b of W.factionAt(p(),w,key))out.push({id:'faction:'+w.id+':'+b.id,label:w.name+' · '+(b.title||human(b.kind)),value:b.text,fork:true});}
 for(const r of p().connections){const label=[r.a,r.b].map(id=>[...p().characters,...p().world].find(x=>x.id===id)?.name||'Someone').join(' & '),state=W.connectionState(p(),r,key);for(const [field,name]of [['bond','Connection'],['aWant','First side wants'],['bWant','Other side wants']])out.push({id:'connection:'+r.id+':'+field,label:label+' · '+name,value:state[field]});}
 return out;
}
actions['record-piece-state']=el=>{
 const n=node(el.dataset.id),edge=el.dataset.edge||'open',sources=pieceStateSources(n,edge);modalData={kind:'record-piece-state',id:n.id,edge,sources};
 dialog('A CHANGE AT THIS MOMENT','What changes?',sources.length?select('Building block, World entry, or connection','source',sources.map(x=>[x.id,x.label]),sources[0].id)+'<p class="help" id="piece-state-before"></p>'+field('New state','value','','What is different now?')+`<label class="check-chip" id="piece-state-fork"><input type="checkbox" name="fork">Keep the current state too · fork into another state</label>`:'<p>Add a character building block, World entry, or connection first.</p>',sources.length?submit('Keep change'):btn('close-dialog','Done','check'),'record-piece-state');updatePieceStatePicker();
};
function updatePieceStatePicker(){if(modalData?.kind!=='record-piece-state')return;const source=modalData.sources.find(x=>x.id===$('#dialog [name=source]')?.value);if(!source)return;$('#piece-state-before').textContent='Currently: '+(source.value||'Not specified');$('#piece-state-fork').hidden=!source.fork;if(!source.fork)$('#piece-state-fork input').checked=false;}
document.addEventListener('change',e=>{if(e.target.name==='source')updatePieceStatePicker();});

const threadToolsSubmit=extraSubmit;extraSubmit=function(form,data,m){
 if(form.dataset.form==='record-piece-state'){if(mutate('Recorded a state change',()=>W.setPieceState(p(),node(m.id),String(data.get('source')),m.edge,String(data.get('value')||''),{fork:data.has('fork')})))closeDialog();return true;}

 if(form.dataset.form==='thread-links'){if(mutate('Updated thread links',()=>W.setAdvancedThreads(p(),node(m.id),data.getAll('threads'))))closeDialog();return true;}
 if(form.dataset.form==='fork-piece-state'){if(mutate('Forked building block',()=>W.setPieceState(p(),node(m.id),m.changeId,m.edge,String(data.get('value')||''),{fork:true})))closeDialog();return true;}
 return threadToolsSubmit(form,data,m);
};
document.addEventListener('change',e=>{
 const el=e.target;if(el.dataset.threadField){mutate('Edited thread plan',()=>W.setThreadPlan(node(el.dataset.id),el.dataset.threadField,el.value,el.dataset.outcome),{rerender:false,notify:false});return;}
 if(el.dataset.pieceState){mutate('Edited recorded state',()=>W.setPieceState(p(),node(el.dataset.id),el.dataset.pieceState,el.dataset.edge,el.value),{rerender:false,notify:false});refreshStateFields();}
});
function alignOpenBeats(){
 for(const el of $$('.node.scene[data-flow-owner]')){el.style.removeProperty('--beat-reach');const owner=$(`[data-node="${CSS.escape(el.dataset.flowOwner)}"]`);if(!owner||!owner.contains(el))continue;const target=owner.querySelector(':scope > .node-children');if(!target)continue;const reach=Math.max(0,el.getBoundingClientRect().left-target.getBoundingClientRect().left);if(reach>10)el.style.setProperty('--beat-reach',reach+'px');}
}
window.addEventListener('resize',()=>requestAnimationFrame(alignOpenBeats));

const arcLabel=row=>row.label||(row.kind==='custom'?'State':kind(row.kind).label);
function characterArcHeader(n,edge='from',view='outline'){
 const a=W.characterArc(p(),n),c=W.arcSubject(p(),a),states=W.arcStateOptions(p(),c),listId='arc-options-'+view+'-'+n.id+'-'+edge;
 const state=(row,side,value=row[side])=>`<span class="arc-state ${value.text?'':'is-empty'}" data-arc-row="${row.id}"><span class="arc-state-label">${esc(arcLabel(row))}</span><input class="arc-state-text" data-arc-inline="${n.id}" data-row="${row.id}" data-edge="${side}" data-outcome="${value.id||''}" value="${esc(value.text)}" placeholder="Add state…" maxlength="1000" list="${listId}" style="--state-chars:${Math.min(36,Math.max(10,value.text.length+1))}ch" aria-label="${side==='from'?'Starting':'Ending'} ${esc(arcLabel(row))}${value.id?' · additional outcome':''}" title="${esc(value.text)}"><button type="button" class="arc-state-options" ${act('arc-state',n.id,`data-edge="${side}" data-row="${row.id}" data-outcome="${value.id||''}"`)} aria-label="Options for ${side==='from'?'starting':'ending'} ${esc(arcLabel(row))}${value.id?' · additional outcome':''}">${icon('edit')}</button></span>`;
 const rows=side=>a.changes.map(row=>`<div class="arc-state-group" data-arc-group="${row.id}">${(side==='from'?[row.from]:[row.to,...(row.outcomes||[])]).map(value=>state(row,side,value)).join('')}${side==='to'?`<button type="button" class="arc-fork" ${act('arc-fork',n.id,`data-row="${row.id}"`)} aria-label="Add another ${esc(arcLabel(row))} outcome" title="Split into another outcome">${icon('plus')}</button>`:''}</div>`).join('');
 return `<div class="character-arc-heading arc-edge-${edge}" role="group" aria-label="${edge==='from'?'Starting':edge==='to'?'Ending':'All'} character states">${edge!=='to'?`<div class="arc-subject">${c?.type==='group'?icon('world'):c?avatar(c):''}<select data-arc-subject="${n.id}" aria-label="Character or group">${opts([['','Choose who changes'],...W.arcSubjects(p()).map(c=>[c.id,c.name+(c.type==='group'?' · Group':'')]),['new','＋ New character'],['new-group','＋ New group']],a.subjectId)}</select></div>`:''}<div class="arc-states">${edge==='both'?`<span class="arc-edge-label">Starts</span>${rows('from')}<span class="arc-edge-label">Ends</span>${rows('to')}`:rows(edge)}${edge!=='to'?`<button type="button" class="text-btn arc-add-change" ${act('arc-add-change',n.id)} aria-label="Add state change">${icon('plus')}<span>State</span></button>`:''}</div><datalist id="${listId}">${states.map(b=>`<option value="${esc(b.text)}">${esc(b.label||kind(b.kind).label)}</option>`).join('')}</datalist></div>`;
}
actions['arc-overview']=el=>{const n=node(el.dataset.id);if(!n)return;modalData={kind:'arc-overview',id:n.id};dialog('CHARACTER THREAD','Title & states',`<input class="arc-title-editor" data-inline="node" data-id="${n.id}" data-field="title" value="${esc(W.editableTitle(p(),n))}" maxlength="1000" aria-label="Thread title" placeholder="Name this thread…">${characterArcHeader(n,'both','dialog')}`,btn('close-dialog','Done','check'));};
// Inline state edits keep the existing timed block link and commit on blur/Enter.
document.addEventListener('change',e=>{
 const el=e.target;if(el.dataset.arcSubject){const id=el.dataset.arcSubject,value=el.value;if(['new','new-group'].includes(value)){editArcPerson(id);$('#dialog [name=arcCharacter]').value=value;updateArcEditor();$('#dialog [name=arcName]')?.focus();return;}mutate('Changed thread subject',()=>W.setArcCharacter(p(),node(id),value));return;}
 if(!el.dataset.arcInline)return;
 const n=node(el.dataset.arcInline),a=W.characterArc(p(),n),row=a.changes.find(r=>r.id===el.dataset.row),c=W.arcSubject(p(),a),side=el.dataset.edge,current=el.dataset.outcome?row.outcomes.find(v=>v.id===el.dataset.outcome):row[side];
 const matching=W.arcStateOptions(p(),c).find(b=>b.text===el.value),partner=side==='to'&&!el.dataset.outcome?row.from:null;
 const blockId=matching?.id||(current.linked?current.blockId:current.text?'':partner?.linked?partner.blockId:c?'new':'');
 mutate('Edited character state',()=>W.setArcState(p(),n,side,{rowId:row.id,outcomeId:el.dataset.outcome,value:el.value,blockId,kind:matching?.kind||row.kind}),{rerender:false,notify:false});
 el.style.setProperty('--state-chars',Math.min(36,Math.max(10,el.value.length+1))+'ch');el.title=el.value;refreshStateFields();
});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-arc-inline],[data-beat-inline],[data-thread-field],[data-piece-state]')&&e.key==='Enter'){e.preventDefault();e.target.blur();}});
// Save during typing as well as on blur; leaving a tab flushes the pending field.
let pendingStateField=null,stateSaveTimer=0;
document.addEventListener('input',e=>{if(e.target.matches('[data-arc-inline],[data-beat-inline],[data-thread-field],[data-piece-state]')){pendingStateField=e.target;clearTimeout(stateSaveTimer);stateSaveTimer=setTimeout(flushStateField,250);const status=$('#save-status');if(status)status.textContent='Saving on this device…';}});
document.addEventListener('change',e=>{if(e.target===pendingStateField){pendingStateField=null;clearTimeout(stateSaveTimer);}});
function flushStateField(){clearTimeout(stateSaveTimer);const field=pendingStateField;pendingStateField=null;if(field?.isConnected)field.dispatchEvent(new Event('change',{bubbles:true}));}
window.addEventListener('beforeunload',flushStateField,{capture:true});
