function editArcPerson(id){
 const n=node(id);if(!n)return;const a=W.characterArc(p(),n);modalData={kind:'arc-person',id};
 dialog('WHO CHANGES','Who is this thread about?',select('Character or group','arcCharacter',[['','Leave unassigned'],...W.arcSubjects(p()).map(c=>[c.id,c.name+(c.type==='group'?' · Group':'')]),['new','＋ Create a character'],['new-group','＋ Create a group']],a.subjectId)+`<div id="arc-new-person" hidden>${field('Name','arcName','','A name or working name')}</div><p class="help">Choose whose arc this is. Other people can be involved without sharing the same change.</p><p class="help">Choosing a different subject clears these title states. Recorded history stays intact.</p>`,submit('Keep subject'),'arc-person');
}
function editArcState(id,edge,rowId='',outcomeId=''){
 const n=node(id);if(!n||!['from','to'].includes(edge))return;
 const a=W.characterArc(p(),n),row=a.changes.find(r=>r.id===rowId)||a.changes[0],c=W.arcSubject(p(),a),states=W.arcStateOptions(p(),c),blocks=[...new Map(states.map(b=>[b.id,b])).values()];
 const current=outcomeId?(row.outcomes||[]).find(v=>v.id===outcomeId):row[edge];if(!current)return;
 const suggestedBlock=current.blockId||(outcomeId?'new':row[edge==='from'?'to':'from'].blockId)||'';
 modalData={kind:'arc-state',id,edge,rowId:row.id,outcomeId,states};
 dialog(c?'A STATE OF '+esc(c.name.toUpperCase()):'A CHARACTER IN THE MAKING',edge==='from'?'Where they begin':'Who they become',
  (states.length?select('Start with an existing state','arcSource',[['','Write a state'],...states.map((b,i)=>[String(i),(b.label||b.title||kind(b.kind).label)+' · '+b.text])],''):'')+
  field('State · optional','arcText',current.text,edge==='from'?'Innocent civilian…':'Communist agent…','textarea')+
  (c?select('Connect to a building block','arcBlock',[['','Keep as title wording'],...blocks.map(b=>[b.id,b.label||b.title||kind(b.kind).label]),['new','＋ New building block']],suggestedBlock):'')+
  `<div id="arc-new-block">${select('Type of change','arcKind',c?.type==='group'?['want','method','value','boundary','capability','obligation','custom'].map(id=>[id,human(id)]):Object.entries(KINDS).map(([id,k])=>[id,k.label]),row.kind)}</div><p class="help" id="arc-state-effect"></p>`+
  '<p class="help">Leave the state blank to keep it open. Clearing a field or removing a pair from this title keeps recorded history.</p>'+
  (a.legacyTitle?disclosure('Previous title',`<p>${esc(a.legacyTitle)}</p>`):''),btn(outcomeId?'arc-remove-outcome':'arc-remove-change',outcomeId?'Remove this outcome':'Remove this pair','close',false,`data-id="${id}" data-row="${row.id}" data-outcome="${outcomeId}"`)+submit('Keep state'),'arc-state');
 updateArcEditor();
}
function updateArcEditor(){
 const form=$('#dialog form');if(!form)return;
 if(form.dataset.form==='arc-person'){$('#arc-new-person').hidden=!['new','new-group'].includes(form.elements.arcCharacter.value);return;}
 if(form.dataset.form!=='arc-state')return;
 const block=form.elements.arcBlock?.value||'',text=form.elements.arcText.value.trim();
 if($('#arc-new-block'))$('#arc-new-block').hidden=!!block&&block!=='new';
 if($('#arc-state-effect'))$('#arc-state-effect').textContent=block&&text?'This saves the building block at this thread’s '+(modalData.edge==='from'?'opening':'closing')+'. Earlier states are preserved.':'This keeps wording in the title without changing recorded states.';
 form.querySelector('[type=submit]').disabled=text.length>1000;
 $('#form-error').textContent=text.length>1000?'Keep this state within 1,000 characters.':'';
}
actions['arc-person']=el=>editArcPerson(el.dataset.id);actions['arc-state']=el=>editArcState(el.dataset.id,el.dataset.edge,el.dataset.row,el.dataset.outcome);
actions['arc-fork']=el=>{let outcomeId;if(mutate('Forked state change',()=>{outcomeId=W.addArcOutcome(p(),node(el.dataset.id),el.dataset.row);}))editArcState(el.dataset.id,'to',el.dataset.row,outcomeId);};
actions['arc-remove-outcome']=el=>{if(mutate('Removed outcome from title',()=>W.removeArcOutcome(p(),node(el.dataset.id),el.dataset.row,el.dataset.outcome)))closeDialog();};
actions['arc-add-change']=el=>{let rowId;if(mutate('Added state pair',()=>{rowId=W.addArcChange(p(),node(el.dataset.id));}))editArcState(el.dataset.id,'from',rowId);};
actions['arc-remove-change']=el=>{if(mutate('Removed state pair from title',()=>W.removeArcChange(p(),node(el.dataset.id),el.dataset.row)))closeDialog();};
document.addEventListener('change',e=>{
 if(!e.target.closest('[data-form="arc-person"],[data-form="arc-state"]'))return;
 if(e.target.name==='arcSource'&&e.target.value!==''){
  const state=modalData.states[Number(e.target.value)],form=e.target.form;
  if(state){form.elements.arcText.value=state.text;form.elements.arcBlock.value=state.id;}
 }
 updateArcEditor();captureFormDraft();
});
document.addEventListener('input',e=>{if(e.target.closest('[data-form="arc-state"]'))updateArcEditor();});
draftable.add('record-piece-state');draftable.add('fork-piece-state');draftable.add('arc-person');draftable.add('arc-state');
const arcSubmit=extraSubmit;
extraSubmit=function(form,data,m){
 const v=k=>String(data.get(k)||'').trim();
 if(form.dataset.form==='arc-person'){
  if(['new','new-group'].includes(v('arcCharacter'))&&!v('arcName'))throw Error('Give the new character a name, or leave the thread unassigned.');
  if(mutate('Changed thread character',()=>{const n=node(m.id);if(!n)throw Error('This thread is no longer available.');let id=v('arcCharacter');if(id==='new'){const c=W.character(v('arcName'));p().characters.push(c);id=c.id;}else if(id==='new-group'){const c={id:W.uid(),name:v('arcName'),type:'group',notes:'',faction:{blocks:[],changes:[],checkpoints:[]}};p().world.push(c);id=c.id;}W.setArcCharacter(p(),n,id);})){closeDialog();}return true;
 }
 if(form.dataset.form==='arc-state'){
  if(mutate('Kept character thread state',()=>{const n=node(m.id);if(!n)throw Error('This thread is no longer available.');W.setArcState(p(),n,m.edge,{rowId:m.rowId,outcomeId:m.outcomeId,value:v('arcText'),blockId:v('arcBlock'),kind:v('arcKind')||'custom'});})){closeDialog();}return true;
 }
 return arcSubmit(form,data,m);
};

function refreshStateFields(){
 for(const input of $$('[data-piece-state]')){const n=node(input.dataset.id);if(n&&input!==document.activeElement){const state=W.changeStateAt(p(),input.dataset.pieceState,n.id+':'+input.dataset.edge);if(state.present)input.value=state.value;}}
 for(const input of $$('[data-arc-inline]')){const n=node(input.dataset.arcInline);if(!n)continue;const a=W.characterArc(p(),n),row=a.changes.find(r=>r.id===input.dataset.row),value=input.dataset.outcome?row?.outcomes?.find(v=>v.id===input.dataset.outcome):row?.[input.dataset.edge];if(value&&input!==document.activeElement){input.value=value.text;input.title=value.text;input.style.setProperty('--state-chars',Math.min(36,Math.max(10,value.text.length+1))+'ch');}}
 for(const el of $$('.beat-state-row')){const button=el.querySelector('[data-change]'),n=node(button?.dataset.beatInline||button?.dataset.id);if(!n)continue;const x=W.pieceChanges(p(),n,{nested:false}).find(x=>x.id===button.dataset.change);if(!x)continue;el.querySelector('.beat-state-before').textContent=x.from;const input=el.querySelector('input');if(input&&input!==document.activeElement)input.value=x.to;}
}
function beatChangeRecord(n,x){
 const [type,id,bid]=x.id.split(':'),key=n.id+':open',mid=W.momentId(p(),key),at=r=>r.at===key||r.momentId===mid;
 const subjectKind=['block','life','prominence'].includes(type)?'character':['connection','terms'].includes(type)?'connection':'world',subject=historicalSubject(subjectKind,id);
 if(!subject)return null;
 const collection=type==='block'?'changes':type==='life'?'lifeChanges':type==='prominence'?'prominence.changes':type==='faction'?'faction.changes':['connection','terms'].includes(type)?'changes':'stateChanges';
 const rows=historicalRows(subject,subjectKind).find(([name])=>name===collection)?.[1]||[],record=rows.findLast(r=>at(r)&&(!['block','faction'].includes(type)||r.blockId===bid));
 if(!record)return null;
 const target=['block','faction'].includes(type)?record.block:type==='terms'?record.terms:record,field=['block','faction'].includes(type)?'text':type==='world'||type==='prominence'?'value':type==='connection'?bid:null;
 return {type,id,bid,subjectKind,collection,record,target,field};
}
function beatStateChanges(n){
 const changes=W.pieceChanges(p(),n,{nested:false});
 return `<div class="beat-states" role="group" aria-label="State changes in this beat">${changes.map(x=>{const ref=beatChangeRecord(n,x);return `<div class="beat-state-row"><span class="beat-state-subject">${esc(x.subject)}</span><span class="beat-state-kind">${esc(human(x.label))}</span><span class="beat-state-before" title="${esc(x.from)}">${esc(x.from)}</span><span class="state-arrow" aria-label="to">→</span>${ref?.field&&ref.target?`<input class="beat-state-after" data-beat-inline="${n.id}" data-change="${esc(x.id)}" value="${esc(x.to)}" aria-label="${esc(x.subject)} · ${esc(human(x.label))} after this beat" title="${esc(x.to)}" style="--state-chars:${Math.min(36,Math.max(10,x.to.length+1))}ch" maxlength="1000">`:`<span class="beat-state-after">${esc(x.to)}</span>`}<button type="button" class="arc-state-options" ${act('beat-change-options',n.id,`data-change="${esc(x.id)}"`)} aria-label="Edit ${esc(x.subject)} ${esc(human(x.label))} change">${icon('edit')}</button>${ref?.target&&['block','faction'].includes(ref.type)?`<button type="button" class="arc-fork" ${act('fork-piece-state',n.id,`data-change="${esc(x.id)}" data-edge="open"`)} aria-label="Fork ${esc(x.subject+' '+human(x.label))}" title="Add a parallel state">${icon('plus')}</button>`:''}</div>`;}).join('')}</div>`;
}
actions['beat-change-options']=el=>{const n=node(el.dataset.id),x=W.pieceChanges(p(),n,{nested:false}).find(x=>x.id===el.dataset.change),ref=x&&beatChangeRecord(n,x);if(ref)editHistoricalRecord(ref.subjectKind,ref.id,ref.collection,ref.record.id);else consequenceDialog(n.id+':open');};
document.addEventListener('change',e=>{const el=e.target;if(!el.dataset.beatInline)return;const n=node(el.dataset.beatInline),x=W.pieceChanges(p(),n,{nested:false}).find(x=>x.id===el.dataset.change),ref=x&&beatChangeRecord(n,x);if(ref?.target&&ref.field)mutate('Edited beat state',()=>{ref.target[ref.field]=el.value.trim();},{rerender:false,notify:false});refreshStateFields();});

