/* Selection is view state. One bulk operation is one saved, undoable edit. */
function bulkCheckbox(n){return ui.bulkMode?`<label class="bulk-piece-check"><input type="checkbox" data-bulk-id="${n.id}" ${ui.bulkIds.has(n.id)?'checked':''} aria-label="Select ${esc(name(n))}"><span class="arc-accessible-title">Select piece</span></label>`:'';}
function bulkToolbar(){
 if(!['outline','sequence','chronology','choices'].includes(ui.mode))return '';
 if(!p().nodes.length)return '';
 if(!ui.bulkMode)return '';
 return `<div class="bulk-toolbar" role="region" aria-label="Selected story pieces"><strong aria-live="polite">${ui.bulkIds.size} selected</strong>${btn('bulk-all','Select all in view','check')}${btn('bulk-clear','Clear','close',false,ui.bulkIds.size?'':'disabled')}<span class="bulk-help">Choose threads and beats individually.</span>${btn('bulk-edit','Apply to selected','edit',true,ui.bulkIds.size?'':'disabled')}${btn('bulk-toggle','Done selecting','check',false,'aria-pressed="true"')}</div>`;
}
function renderedBulkIds(){return [...new Set($$('[data-bulk-id]').filter(el=>el.getBoundingClientRect().width).map(el=>el.dataset.bulkId))];}
actions['bulk-toggle']=()=>{brush='';ui.bulkMode=!ui.bulkMode;if(!ui.bulkMode){ui.bulkIds.clear();ui.bulkAnchor='';}render();};
