document.addEventListener('click',e=>{
 const input=e.target.closest('[data-bulk-id]');if(!input)return;const id=input.dataset.bulkId,checked=input.checked,ids=renderedBulkIds(),from=ids.indexOf(ui.bulkAnchor),to=ids.indexOf(id);
 const range=e.shiftKey&&from>=0?ids.slice(Math.min(from,to),Math.max(from,to)+1):[id];
 for(const value of range)if(checked)ui.bulkIds.add(value);else ui.bulkIds.delete(value);ui.bulkAnchor=id;render();$(`[data-bulk-id="${CSS.escape(id)}"]`)?.focus();
});
function editBulk(ids){
 const pieces=ids.map(node).filter(Boolean);if(!pieces.length){toast('Select a few pieces first.');return;}
 modalData={kind:'bulk-edit',ids:pieces.map(n=>n.id)};
 const picker=(title,name,items)=>disclosure(title,items.length?`<input class="bulk-search" type="search" aria-label="Search ${esc(title.toLowerCase())}" placeholder="Search…" data-bulk-search="${name}"><div class="bulk-options" data-bulk-options="${name}">${items.map(x=>`<label class="check-chip"><input type="checkbox" name="${name}" value="${x.id}">${esc(x.name)}</label>`).join('')}</div>`:'<p class="help">Nothing available yet.</p>');
 dialog('EDIT TOGETHER',`Apply to ${pieces.length} ${pieces.length===1?'piece':'pieces'}`,`<p class="help">People, World entries, and plots are added to the existing choices. Viewpoint and status replace the current value. Both ends of each selected thread are included.</p>`+
 picker('Add people','bulkCast',p().characters)+picker('Add settings, items & World entries','bulkWorld',p().world.map(w=>({...w,name:w.name+' · '+human(w.type)})))+
 `<div class="two-fields">${select('Viewpoint (POV)','bulkPov',[['unchanged','Leave unchanged'],['clear','Clear viewpoint'],...p().characters.map(c=>[c.id,c.name])],'unchanged')}${select('Outline status','bulkStatus',[['','Leave unchanged'],['open','In progress'],['planned','Planned'],['resolved','Resolved'],['open-ended','Intentionally left open']],'')}</div>`+
 picker('Add to plots','bulkPlots',(p().plots||[]).map(x=>({id:x.id,name:x.label+' plot · '+x.title})))+
 disclosure('Selected pieces',`<ul class="bulk-preview">${pieces.map(n=>`<li>${esc(W.TYPES[n.type].name)} · ${esc(name(n))}</li>`).join('')}</ul>`)+
 '<p class="help">A viewpoint character is also added to the cast. Nested pieces change only when selected. You can undo the whole batch in one step.</p>',submit('Apply changes'),'bulk-edit');updateBulkEditor();
}
function updateBulkEditor(){const form=$('#dialog form[data-form="bulk-edit"]');if(!form)return;form.querySelector('[type=submit]').disabled=!form.querySelector('input:checked')&&form.elements.bulkPov.value==='unchanged'&&!form.elements.bulkStatus.value;}
document.addEventListener('change',e=>{if(e.target.closest('[data-form="bulk-edit"]'))updateBulkEditor();});
document.addEventListener('input',e=>{if(!e.target.dataset.bulkSearch)return;const list=e.target.form.querySelector(`[data-bulk-options="${e.target.dataset.bulkSearch}"]`),q=e.target.value.toLocaleLowerCase();for(const label of list.querySelectorAll('label'))label.hidden=!label.textContent.toLocaleLowerCase().includes(q);});
draftable.add('bulk-edit');
const bulkSubmit=extraSubmit;extraSubmit=function(form,data,m){
 if(form.dataset.form==='bulk-edit'){
  const pov=String(data.get('bulkPov')||'unchanged'),status=String(data.get('bulkStatus')||'');
  if(mutate('Updated '+m.ids.length+' pieces',()=>W.applyBulk(p(),m.ids,{cast:data.getAll('bulkCast').map(String),worldIds:data.getAll('bulkWorld').map(String),plotIds:data.getAll('bulkPlots').map(String),povId:pov==='unchanged'?null:pov==='clear'?'':pov,status:status||null})))closeDialog();return true;
 }
 return bulkSubmit(form,data,m);
};
